   for(int i=0;i<8;++i){std::string s="sl"+std::to_string(i);zone(s,"Slice "+std::to_string(i+1),"break-source","break",24+i,24+i,1,127,24+i);tables_["slice"].push_back(make(s,{{"source","break-source"},{"name","Slice "+std::to_string(i+1)},{"start",decimal(i/8.)},{"end",decimal((i+1)/8.)}}));}
