 for(auto [id,label,unit,group,value,minimum,maximum]:std::vector<std::tuple<std::string,std::string,std::string,std::string,double,double,double>>{{"pitch-key-track","Key track","%","Pitch",1,0,2},{"bend","Bend","st","Pitch",2,0,48},{"filter-key-track","Key track","%","Filter",.5,0,1},{"filter-env-amount","Envelope amount","%","Filter",.42,-1,1},{"source-gain","Gain","dB","Source",-1.5,-60,12}})tables_["parameter"].push_back(make(id,{{"label",label},{"unit",unit},{"group",group},{"value",decimal(value)},{"default",decimal(value)},{"minimum",decimal(minimum)},{"maximum",decimal(maximum)},{"step",unit=="%"?"0.01":"1"}}));set("filter-mode","lp");
 for(auto [mid,label,val,destinations]:std::vector<std::array<std::string,4>>{{"tone","Tone","0.56","cutoff;resonance;filter-sustain"},{"body","Body","0.4","level;amp-sustain"},{"space","Space","0.32","reverb-mix"},{"drive-macro","Drive","0.18","drive;level"},{"snap","Snap","0.64","amp-attack"},{"width","Width","0.5","pan"},{"macro7","Macro 7","0",""},{"macro8","Macro 8","0",""}}){tables_["macro"].push_back(make(mid,{{"name",label},{"value",val},{"default",val},{"minimum","0"},{"maximum","1"},{"destinations",destinations},{"host",mid=="space"?"1":"0"}}));std::istringstream parts{destinations};std::string destination;while(std::getline(parts,destination,';'))if(!destination.empty())tables_["binding"].push_back(make(mid+":"+destination,{{"macro",mid},{"destination",destination},{"amount","0.5"},{"on","1"}}));}set("selected-macro","tone");set("midi-cc",-1);
