 tables_["fx"].clear();tables_["fx"].push_back(make("eq",{{"name","Parametric EQ"},{"parent","main"},{"order","0"},{"bypassed","0"}}));tables_["fx"].push_back(make("reverb-fx",{{"name","Reverb"},{"parent","main"},{"order","1"},{"bypassed","0"}}));
